function isValidPermission(key: string): key is ValidPermission {
  return VALID_PERMISSIONS.includes(key);
}

export function buildAllowAttribute(permissions: McpUiResourcePermissions): string {
  return Object.keys(permissions)
    .filter(isValidPermission)
    .filter(key => permissions[key])
    .map(key => PERMISSION_MAPPINGS[key])
    .join("; ");
}

